mapper.sql:
SELECT id, prompt_key AS promptKey, prompt_name AS promptName, prompt_content AS promptContent, scope, scope_id AS scopeId, status, description, created_by AS createdBy, created_at AS createdAt, updated_at AS updatedAt FROM sys_prompts WHERE 1=1 AND scope = #{scope}
AND (prompt_name LIKE #{keyword} OR prompt_key LIKE #{keyword} OR prompt_content LIKE #{keyword})
ORDER BY scope, prompt_key

mapper.update:
UPDATE sys_prompts
prompt_key = #{row.promptKey}, prompt_name = #{row.promptName}, prompt_content = #{row.promptContent}, scope = #{row.scope}, scope_id = #{row.scopeId}, version = #{row.version}, status = #{row.status}, description = #{row.description}, updated_at = NOW()
WHERE id = #{id}
